mapper.select:
select token_id from ontology_mcp_token
where token_hash = #{tokenHash} and status = #{status}
limit 1

select asset_id, asset_name, asset_type, domain_name, description
from wiki_asset
where status = #{status} and space_id = #{spaceId}
  and (asset_name like #{like} or description like #{like} or content like #{like})
order by update_time desc
limit #{limit}

select asset_id, asset_name, asset_type, domain_name, description
from wiki_asset
where status = #{status}
  and (asset_name like #{like} or description like #{like} or content like #{like})
order by update_time desc
limit #{limit}

select task_id, task_name, status, summary, create_by, create_time, update_time
from analysis_task
where status = #{status}
order by update_time desc
limit #{limit}

select task_id, task_name, status, summary, update_time
from analysis_task
where task_id = #{taskId}
